import{_ as t,o as i,c as a,a3 as o}from"./chunks/framework.BveOjhN0.js";const v=JSON.parse('{"title":"Tenant API v1 — Activities","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Activities | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-activities"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Activities | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-activities"}]]},"headers":[],"relativePath":"api/tenant-v1-activities.md","filePath":"api/tenant-v1-activities.md","lastUpdated":1785449119000}'),c={name:"api/tenant-v1-activities.md"};function d(s,e,n,r,l,p){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tenant-api-v1-—-activities" tabindex="-1">Tenant API v1 — Activities <a class="header-anchor" href="#tenant-api-v1-—-activities" aria-label="Permalink to &quot;Tenant API v1 — Activities&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:activities</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>activities.assign</code> (and not superadmin), list/stats/view/update only include activities where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-activities-stats" tabindex="-1">GET <code>/activities/stats</code> <a class="header-anchor" href="#get-activities-stats" aria-label="Permalink to &quot;GET `/activities/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_activities</code>, <code>my_activities</code>, <code>open</code>, <code>completed</code>, <code>due_soon</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="activities-crud" tabindex="-1">Activities CRUD <a class="header-anchor" href="#activities-crud" aria-label="Permalink to &quot;Activities CRUD&quot;">​</a></h2><h3 id="get-activities" tabindex="-1">GET <code>/activities</code> <a class="header-anchor" href="#get-activities" aria-label="Permalink to &quot;GET `/activities`&quot;">​</a></h3><p>Query: <code>search</code>, <code>type</code>, <code>status</code> (<code>open</code>|<code>completed</code>), <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_activities</code>, <code>contact_id</code>, <code>company_id</code>, <code>lead_id</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include related <code>contact</code> / <code>company</code> / <code>lead</code> refs when loaded, <code>is_completed</code>, and <code>latest_note</code>.</p><h3 id="post-activities" tabindex="-1">POST <code>/activities</code> <a class="header-anchor" href="#post-activities" aria-label="Permalink to &quot;POST `/activities`&quot;">​</a></h3><p>Body: <code>type</code> (required: <code>call</code>|<code>email</code>|<code>note</code>|<code>follow_up</code>|<code>other</code>), <code>subject</code> (required), <code>body</code>, <code>due_at</code>, <code>contact_id</code>, <code>company_id</code>, <code>lead_id</code>, <code>assigned_to</code>.</p><p>At least one of <code>contact_id</code>, <code>company_id</code>, <code>lead_id</code> is required. Each FK requires the corresponding module to be entitled.</p><h3 id="get-activities-id" tabindex="-1">GET <code>/activities/{id}</code> <a class="header-anchor" href="#get-activities-id" aria-label="Permalink to &quot;GET `/activities/{id}`&quot;">​</a></h3><p>Includes assignee, creator, notes, timeline activities, and related refs.</p><h3 id="put-activities-id" tabindex="-1">PUT <code>/activities/{id}</code> <a class="header-anchor" href="#put-activities-id" aria-label="Permalink to &quot;PUT `/activities/{id}`&quot;">​</a></h3><p>Partial update. Clearing all related FKs is rejected.</p><h3 id="delete-activities-id" tabindex="-1">DELETE <code>/activities/{id}</code> <a class="header-anchor" href="#delete-activities-id" aria-label="Permalink to &quot;DELETE `/activities/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>activities.delete</code>.</p><h3 id="post-activities-id-restore" tabindex="-1">POST <code>/activities/{id}/restore</code> <a class="header-anchor" href="#post-activities-id-restore" aria-label="Permalink to &quot;POST `/activities/{id}/restore`&quot;">​</a></h3><p>Permission: <code>activities.restore</code>.</p><h3 id="delete-activities-id-force" tabindex="-1">DELETE <code>/activities/{id}/force</code> <a class="header-anchor" href="#delete-activities-id-force" aria-label="Permalink to &quot;DELETE `/activities/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted activity. Permission: <code>activities.force.delete</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-activities-id-assign" tabindex="-1">POST <code>/activities/{id}/assign</code> <a class="header-anchor" href="#post-activities-id-assign" aria-label="Permalink to &quot;POST `/activities/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><h3 id="post-activities-id-complete" tabindex="-1">POST <code>/activities/{id}/complete</code> <a class="header-anchor" href="#post-activities-id-complete" aria-label="Permalink to &quot;POST `/activities/{id}/complete`&quot;">​</a></h3><p>Sets <code>completed_at</code> (idempotent if already completed). Permission: <code>activities.complete</code>.</p><h3 id="post-activities-id-notes" tabindex="-1">POST <code>/activities/{id}/notes</code> <a class="header-anchor" href="#post-activities-id-notes" aria-label="Permalink to &quot;POST `/activities/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="get-activities-id-timeline" tabindex="-1">GET <code>/activities/{id}/timeline</code> <a class="header-anchor" href="#get-activities-id-timeline" aria-label="Permalink to &quot;GET `/activities/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries for the engagement.</p>',34)])])}const m=t(c,[["render",d]]);export{v as __pageData,m as default};
